-- ----------------------------------------------------------------------------
-- 9. OFFICIAL BULLETIN NOTICES (32 Administrative Circulars June - October 2026)
-- Covers Academic, Safety, Facilities, Fees, Rules, and Social Events
-- ----------------------------------------------------------------------------
DELETE FROM notices;

INSERT INTO notices (title, content, date_posted, target_audience) VALUES
('Hostel Room Allocation Commencement - Academic Year 2025/2026', 'All 160 eligible undergraduate students assigned to Blocks A and B are requested to complete room check-in with the Sub Warden office on or before June 5th, 2026. Please bring your student ID and faculty admission slip.', '2026-06-01', 'ALL'),
('Mandatory Sub Warden Welcome & Code of Conduct Briefing', 'A mandatory introductory meeting for all resident students will be held in the Block B Common Hall on Friday, June 5th, at 05:00 PM. The Sub Warden and Chief Security Officer will outline key hostel regulations, curfew policies, and emergency protocols.', '2026-06-03', 'STUDENTS'),
('Student Vehicle & Motorcycle Parking Permit Registration', 'Students keeping motorbikes or bicycles within the university hostel perimeter must register their vehicle details at the Security Main Gate before June 15th to obtain official security parking stickers.', '2026-06-08', 'STUDENTS'),
('Guidelines on Campus Wi-Fi Network Access and Device Registration', 'High-speed campus fiber Wi-Fi is now active across all residential corridors in Blocks A and B. Students may connect up to two academic computing devices using their university email credentials.', '2026-06-12', 'ALL'),
('Maintenance Work Order Submission via Online Digital Portal', 'Please lodge all room repairs, electrical faults, and plumbing issues strictly through the HMS online portal. Do not verbally request staff members in hallways to ensure proper work order tracking and accountability.', '2026-06-18', 'ALL'),
('Notice on Timely Monthly Hostel Fee Settlement - June 2026', 'Students are reminded that the monthly accommodation fee of Rs. 1,500.00 must be remitted prior to the 10th of each calendar month. Official digital receipts are automatically generated in the student portal.', '2026-06-25', 'STUDENTS'),
('Routine Electrical Sockets and Fire Safety Inspection', 'Maintenance and Security personnel will carry out scheduled electrical point safety checks in all Block A rooms on Saturday, July 4th. Resident students are advised to keep rooms accessible.', '2026-07-02', 'ALL'),
('Dengue Prevention Campaign & Hostel Premise Cleaning Drive', 'In collaboration with the University Health Center, a joint campus cleanup and larvicide spraying campaign will take place on July 11th. Students are urged to clear water receptacles and open trays.', '2026-07-07', 'ALL'),
('Hostel Quiet Hours & Study Hall Regulations', 'With continuous assessment tests approaching, silent study hours will be enforced across all dormitory floors between 10:00 PM and 06:00 AM. Loud music, noise, and gatherings are strictly prohibited during these hours.', '2026-07-14', 'STUDENTS'),
('Notice on Monthly Accommodation Fee Settlement - July 2026', 'All resident students residing in Blocks A and B must settle their accommodation fee of Rs. 1,500.00 for July on or before July 31st, 2026 to maintain uninterrupted hostel privileges.', '2026-07-22', 'STUDENTS'),
('Inter-Block Table Tennis and Badminton Tournament', 'Registrations are now open for the annual Inter-Block Indoor Sports Championship scheduled for August 8th in the Gymnasium. Team entries must be submitted to the Student Hostel Committee by August 3rd.', '2026-07-28', 'STUDENTS'),
('Maintenance Notice: Main Water Pump Replacement & Overhaul', 'The Facilities Engineering Division will replace the primary raw water booster pump on Saturday, August 8th between 08:00 AM and 01:00 PM. Water supply from overhead storage will remain available during this window.', '2026-08-04', 'ALL'),
('Annual Fire Safety & Emergency Evacuation Drill', 'The University Safety Directorate will conduct a comprehensive fire drill across Blocks A, B, C, D on August 15th at 10:30 AM. When alarm sirens sound, all occupants must evacuate via marked emergency exits to the sports ground.', '2026-08-10', 'ALL'),
('Extended Study Hall Access during Mid-Semester Exams', 'The ground floor air-conditioned reading room in Block B will remain open 24 hours daily from August 22nd through September 20th to accommodate students preparing for mid-semester assessments.', '2026-08-18', 'STUDENTS'),
('Notice on Monthly Accommodation Fee Settlement - August 2026', 'Students are requested to remit the August 2026 hostel fee of Rs. 1,500.00 prior to August 31st via the online portal. Automated invoices have been posted to student accounts.', '2026-08-24', 'STUDENTS'),
('Hostel Security Advisory: Visitor ID Badges and Curfew Timings', 'Non-resident visitors and day scholars are permitted only in the ground floor visitor lobby until 07:00 PM daily. Visitors must surrender an NIC at the main gate. Overnight non-resident guests are strictly barred.', '2026-09-01', 'ALL'),
('Blood Donation Campaign Organized by Ruhuna Leo Club', 'The Annual University Blood Donation Camp will be held on Thursday, September 10th at the Faculty Auditorium from 09:00 AM to 03:00 PM. All healthy resident students and staff are invited to donate.', '2026-09-05', 'ALL'),
('Semester Examination Curfew & Study Environment Guidelines', 'Absolute silence protocol will be strictly maintained throughout all residential wings from September 15th to October 15th. Gate pass requests will only be authorized for verified medical or compassionate family reasons.', '2026-09-12', 'ALL'),
('Common Kitchen and Pantry Sanitization Schedule', 'Housekeeping staff will carry out deep cleaning and chemical sanitization of all pantry counters, microwaves, and hot water stations every Wednesday from 02:00 PM to 04:00 PM. Please remove personal utensils.', '2026-09-18', 'STUDENTS'),
('Notice on Monthly Accommodation Fee Settlement - September 2026', 'September accommodation dues of Rs. 1,500.00 should be settled before September 30th. Students with pending fees are urged to complete clearance to avoid late registration holds.', '2026-09-23', 'STUDENTS'),
('Notice to Staff: Mandatory Shift Logging on HMS Portal', 'All Security, Maintenance, and Housekeeping staff must ensure their daily shift check-in and check-out timestamps are marked in the presence of department leads. System logs determine monthly duty allowances.', '2026-09-28', 'STAFF'),
('Hostel Accommodation Fee Collection - October 2026', 'All resident students living in Blocks A and B are requested to settle their monthly accommodation fee of Rs. 1,500.00 on or before October 31st, 2026 via the online portal.', '2026-10-01', 'STUDENTS'),
('Inter-Hostel Cricket League - Preliminary Team Registrations', 'Matches for the Ruhuna Inter-Hostel 8-a-side Cricket League will commence on October 25th at the University Main Ground. Block captains must submit confirmed 10-player team sheets to the warden office.', '2026-10-06', 'STUDENTS'),
('Scheduled Pest Control and Insect Fumigation in Common Areas', 'Professional pest control teams will fumigate corridors, washrooms, and external drains on Saturday, October 17th from 08:30 AM to 12:30 PM. Keep room windows closed during spraying.', '2026-10-12', 'ALL'),
('Reminder: Unauthorized Electric Heating Appliances are Strictly Prohibited', 'Use of high-wattage immersion coil heaters, electric hot plates, and induction cookers inside dormitory rooms violates hostel safety bylaws and presents severe fire risk. Confiscations and fines will apply.', '2026-10-15', 'STUDENTS'),
('Security Notice: Extended Gate Curfew for Library Study', 'Main gate curfew for students utilizing the central library late reading room has been extended to 10:30 PM until November 15th upon presentation of a stamped library night pass.', '2026-10-19', 'STUDENTS'),
('Scheduled Main Overhead Water Reservoir Chlorination', 'Please be notified that the main water reservoir will undergo routine descaling and chlorinated disinfection on Thursday, October 29th, from 09:00 AM to 03:00 PM. Water supply will be temporarily paused.', '2026-10-22', 'ALL'),
('Notice to Maintenance Staff: Monthly Preventive Tool Audit', 'All technicians must return specialized electrical meters, pipe threading kits, and welding apparatus to the central engineering store for calibrated inspection on Friday, October 30th.', '2026-10-24', 'MAINTENANCE'),
('Final Reminder: Settlement of October Hostel Fee Arrears', 'Students TG/2021/0001 through TG/2021/0020 who have pending payments for October 2026 are kindly requested to complete payment before October 31st to prevent automated late payment surcharges.', '2026-10-25', 'STUDENTS'),
('Annual Pirith Chanting and Blessing Ceremony at Main Hostel Ground', 'The All-Night Pirith Chanting Ceremony to invoke blessings on all undergraduates, faculty, and non-academic staff will take place on Friday, November 6th at 07:00 PM followed by Morning Alms Giving.', '2026-10-26', 'ALL'),
('Hostel Council Elections 2026/2027: Call for Student Nominations', 'Nomination papers for student representatives (Block A President, Block B President, Sports Secretary, Welfare Secretary) are available at the Sub Warden office until November 2nd at 04:00 PM.', '2026-10-27', 'STUDENTS'),
('Emergency Contacts & Medical Assistance Hotline Directory', 'In the event of an urgent medical condition, electrical hazard, or security emergency, residents may contact: Sub Warden (077-1234567), Main Security Gate (077-0000001), University Ambulance (041-2222681).', '2026-10-27', 'ALL');

